from unittest.mock import patch

from _pytest.compat import getfuncargnames


class AmbiguousBool:
    def __bool__(self):
        raise ValueError("The truth value of an array with more than one element is ambiguous.")


class ArrayLike:
    __hash__ = None

    def __eq__(self, other):
        return AmbiguousBool()


class Target:
    value = None


@patch.object(Target, "value", new=ArrayLike())
def test_with_explicit_array(fixture):
    pass


@patch.object(Target, "value")
def test_with_default_mock(injected, fixture):
    pass


print("explicit new:", getfuncargnames(test_with_explicit_array))
print("default new:", getfuncargnames(test_with_default_mock))
EOF
PYTHONPATH=/testbed/src python /tmp/repro_patch_array.py

cd /testbed && export PYTHONPATH=/testbed/src:/opt/course-public-deps && PY=/opt/miniconda3/envs/testbed/bin/python && cat > /tmp/test_numpy_patch_array_fixed.py <<'EOF'
import numpy as np
import pytest
from unittest.mock import patch


class Target:
    value = None


class Other:
    value = None


@pytest.fixture
def fixture():
    return "fixture"


@patch.object(Target, "value", new=np.array([-5.5, 3.0]))
def test_patch_with_array(fixture):
    assert fixture == "fixture"
    assert Target.value.tolist() == [-5.5, 3.0]


@patch.object(Other, "value")
@patch.object(Target, "value", new=np.array([1.0, 2.0]))
def test_mixed_explicit_and_default(mock_value, fixture):
    assert fixture == "fixture"
    assert Target.value.tolist() == [1.0, 2.0]
    assert mock_value is not None
EOF
